// ═══ VOLATILE: visibility only ═══
volatile boolean running = true;        // (Recommended) flag: one writer, many readers
volatile String latestAlert = "NONE";   // (Recommended) status: one writer sets, many read
volatile Config config;                  // (Recommended) reference: swap entire immutable object

// ═══ ATOMIC: visibility + atomicity ═══
AtomicInteger txnCount = new AtomicInteger(0);
txnCount.incrementAndGet();              // (Recommended) atomic read-modify-write
txnCount.compareAndSet(5, 10);           // (Recommended) atomic conditional update (CAS)
txnCount.getAndUpdate(v -> v * 2);       // (Recommended) atomic function application

AtomicLong totalVolume = new AtomicLong(0);
totalVolume.addAndGet(50000);            // (Recommended) atomic addition

AtomicBoolean initialized = new AtomicBoolean(false);
initialized.compareAndSet(false, true);  // (Recommended) one-time initialization (CAS)

AtomicReference<PriceRange> price = new AtomicReference<>(new PriceRange(100, 105));
price.compareAndSet(oldRange, newRange); // (Recommended) atomic reference swap (with CAS check)

LongAdder highContentionCounter = new LongAdder();
highContentionCounter.increment();       // (Recommended) per-thread cells, sum() to read
// 10x faster than AtomicLong under 64+ threads!

// ═══ DECISION GUIDE ═══
// Need only visibility (read/write of single value)?     → volatile
// Need atomic increment/decrement?                        → AtomicInteger/Long
// Need atomic conditional update (CAS)?                   → AtomicXxx.compareAndSet
// Need high-throughput counter (many threads)?             → LongAdder
// Need atomic reference swap?                             → AtomicReference
// Need to prevent ABA problem?                            → AtomicStampedReference
// Need atomic update of array element?                    → AtomicIntegerArray
// Need compound operation on multiple variables?          → synchronized (not Atomic!)

// ═══ CAS MECHANISM (how Atomic works internally) ═══
// AtomicInteger.incrementAndGet():
//   do {
//     int current = get();           // volatile read
//     int next = current + 1;
//   } while (!compareAndSet(current, next));  // CAS: hardware instruction
//   return next;
//
// CAS: "set value to 'next' ONLY IF current value is still 'current'"
// If another thread changed it → CAS returns false → loop retries!
// Lock-free! No blocking! No deadlock!
// But: under VERY high contention → many retries → use LongAdder instead.
