// ─── File: src/test/java/com/bank/atomics/VolatileVsAtomicTest.java ───
package com.bank.atomics;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class VolatileVsAtomicTest {

    // ═══ volatile: shutdown flag ═══
    static class TradingEngine {
        volatile boolean running = true;
        int tradesProcessed = 0;

        void processLoop() {
            while (running) {
                tradesProcessed++;
                Thread.yield();
            }
        }
        void shutdown() { running = false; }
    }

    @Test
    void volatileFlag_shutdownWorks() throws InterruptedException {
        TradingEngine engine = new TradingEngine();
        Thread worker = new Thread(engine::processLoop);
        worker.start();
        Thread.sleep(50);

        engine.shutdown();
        worker.join(2000);

        assertThat(worker.isAlive()).isFalse();
        assertThat(engine.tradesProcessed).isGreaterThan(0);
    }

    // ═══ AtomicInteger: concurrent counter ═══
    @Test
    void atomicInteger_concurrentCounter() throws InterruptedException {
        AtomicInteger sessions = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                sessions.incrementAndGet();  // login
                sessions.decrementAndGet();  // logout
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(sessions.get()).isEqualTo(0);  // all logged out!
    }

    // ═══ AtomicBoolean: one-time initialization (CAS) ═══
    @Test
    void atomicBoolean_oneTimeInit() throws InterruptedException {
        AtomicBoolean initialized = new AtomicBoolean(false);
        AtomicInteger initCount = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                if (initialized.compareAndSet(false, true)) {
                    initCount.incrementAndGet();  // only ONE thread succeeds!
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(initCount.get()).isEqualTo(1);  // initialized EXACTLY once!
    }

    // ═══ AtomicReference: swap immutable object ═══
    record MarketPrice(String symbol, double bid, double ask) {}

    @Test
    void atomicReference_swapPrice() {
        AtomicReference<MarketPrice> priceRef = new AtomicReference<>(
            new MarketPrice("RELIANCE", 2450.00, 2451.50));

        MarketPrice oldPrice = priceRef.get();
        MarketPrice newPrice = new MarketPrice("RELIANCE", 2452.00, 2453.50);

        boolean swapped = priceRef.compareAndSet(oldPrice, newPrice);
        assertThat(swapped).isTrue();
        assertThat(priceRef.get().bid()).isEqualTo(2452.00);
    }

    // ═══ LongAdder: high-contention counter ═══
    @Test
    void longAdder_highContention() throws InterruptedException {
        LongAdder counter = new LongAdder();
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < 10000; i++) counter.increment();
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(counter.sum()).isEqualTo(1_000_000);
    }
}
